// ============================================================================
// OCP_IP_Open_Core_Protocol_apb: APB4 register wrapper around OCP_IP_Open_Core_Protocol_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/OCP_IP_Open_Core_Protocol.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/OCP_IP_Open_Core_Protocol.md
// ============================================================================
module OCP_IP_Open_Core_Protocol_apb #(
  parameter int DW = 32,
  // data width
  parameter int AW = 32
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic [2:0] MCmd,
  output logic [AW-1:0] MAddr,
  output logic [DW-1:0] MData,
  output logic [3:0] MByteEn,
  output logic [4:0] MBurstLength,
  output logic [2:0] MBurstSeq,
  input logic SCmdAccept,
  input logic [1:0] SResp,
  input logic [DW-1:0] SData,
  input logic SRespLast
);
  localparam logic [31:0] ID_VALUE = 32'h4F500200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [9:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd10) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_req_valid;
  logic          c_req_ready;
  logic          c_req_rw;
  logic          c_req_posted;
  logic [31:0]   c_req_addr;
  logic [4:0]    c_req_len;
  logic [31:0]   c_req_wdata;
  logic          c_resp_valid;
  logic [31:0]   c_resp_rdata;
  logic          c_resp_err;
  logic          c_irq;
  OCP_IP_Open_Core_Protocol_top #(.DW(DW), .AW(AW)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .req_valid(c_req_valid),
    .req_ready(c_req_ready),
    .req_rw(c_req_rw),
    .req_posted(c_req_posted),
    .req_addr(c_req_addr),
    .req_len(c_req_len),
    .req_wdata(c_req_wdata),
    .resp_valid(c_resp_valid),
    .resp_rdata(c_resp_rdata),
    .resp_err(c_resp_err),
    .MCmd(MCmd),
    .MAddr(MAddr),
    .MData(MData),
    .MByteEn(MByteEn),
    .MBurstLength(MBurstLength),
    .MBurstSeq(MBurstSeq),
    .SCmdAccept(SCmdAccept),
    .SResp(SResp),
    .SData(SData),
    .SRespLast(SRespLast),
    .irq(c_irq)
  );

  // ---------------- registers ----------------
  logic [4:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [31:0] h_REQ0;   // 12'h014 REQ0 holding register
  logic [31:0] h_REQ1;   // 12'h018 REQ1 holding register
  logic [6:0] h_REQ2;   // 12'h01C REQ2 holding register
  logic [31:0] h_RESP0;   // 12'h020 RESP0 holding register
  logic [0:0] h_RESP1;   // 12'h024 RESP1 holding register
  logic full_REQ;
  logic avail_RESP;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      h_REQ0 <= '0;
      h_REQ1 <= '0;
      h_REQ2 <= '0;
      h_RESP0 <= '0;
      h_RESP1 <= '0;
      full_REQ <= 1'b0;
      avail_RESP <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[4:0] & wmask[4:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[4:0]) | (PWDATA[4:0] & wmask[4:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5] && !full_REQ) h_REQ0 <= (h_REQ0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[6] && !full_REQ) h_REQ1 <= (h_REQ1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7] && !full_REQ) h_REQ2 <= (h_REQ2 & ~wmask[6:0]) | (PWDATA[6:0] & wmask[6:0]);
      if (wr && hit[7] && !full_REQ) full_REQ <= 1'b1;
      else if (full_REQ && c_req_ready) full_REQ <= 1'b0;
      if (c_resp_valid && (!avail_RESP || (rd && hit[9]))) begin
        h_RESP0[31:0] <= c_resp_rdata[31:0];
        h_RESP1 <= c_resp_err;
        avail_RESP <= 1'b1;
      end else if (rd && hit[9]) avail_RESP <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_req_addr[31:0] = h_REQ0[31:0];
  assign c_req_wdata[31:0] = h_REQ1[31:0];
  assign c_req_rw = h_REQ2[0:0];
  assign c_req_posted = h_REQ2[1:1];
  assign c_req_len[4:0] = h_REQ2[6:2];
  assign c_req_valid = full_REQ;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_irq;
    irq_set[1] = full_REQ & c_req_ready;
    irq_set[2] = wr & (hit[5] | hit[6] | hit[7]) & full_REQ;
    irq_set[3] = c_resp_valid & (~avail_RESP | (rd & hit[9]));
    irq_set[4] = c_resp_valid & avail_RESP & ~(rd & hit[9]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_RESP, full_REQ};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(h_REQ0);
      10'd6: apb_rdata = 32'(h_REQ1);
      10'd7: apb_rdata = 32'(h_REQ2);
      10'd8: apb_rdata = 32'(h_RESP0);
      10'd9: apb_rdata = 32'(h_RESP1);
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
